SINA_SMART["anat3-blood-supply"] = {"lecture":"anat3-blood-supply","title":"Blood supply of the facio-maxillary region","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"anat3-blood-supply:s0","text":"Describe and explain: The big picture","topic":"The big picture","sec":0,"importance":"standard","highYield":"untested"},{"id":"anat3-blood-supply:s1","text":"Describe and explain: What the lecture asks you to do","topic":"What the lecture asks you to do","sec":1,"importance":"standard","highYield":"untested"},{"id":"anat3-blood-supply:e0","text":"Right common carotid from the brachiocephalic trunk; left directly from the aortic arch.","topic":"From the aorta to the carotid bifurcation","sec":2,"importance":"core","highYield":"untested"},{"id":"anat3-blood-supply:e1","text":"Carotid bifurcation: carotid triangle, upper border of the thyroid cartilage, C3 to C4 disc.","topic":"From the aorta to the carotid bifurcation","sec":2,"importance":"core","highYield":"untested"},{"id":"anat3-blood-supply:e2","text":"External carotid begins anteromedial to the internal carotid and ends lateral to it.","topic":"External carotid artery: course and relations","sec":3,"importance":"core","highYield":"untested"},{"id":"anat3-blood-supply:e3","text":"It terminates in the parotid gland behind the neck of the mandible as the superficial temporal and maxillary arteries.","topic":"External carotid artery: course and relations","sec":3,"importance":"core","highYield":"untested"},{"id":"anat3-blood-supply:s4","text":"Describe and explain: The eight branches of the external carotid","topic":"The eight branches of the external carotid","sec":4,"importance":"standard","highYield":"untested"},{"id":"anat3-blood-supply:e10","text":"Maxillary artery: three parts (mandibular, pterygoid, pterygopalatine), five branches each; the middle meningeal enters the foramen spinosum.","topic":"Branch by branch","sec":5,"importance":"core","highYield":"untested"},{"id":"anat3-blood-supply:e4","text":"Eight branches: superior thyroid, ascending pharyngeal, lingual, facial, occipital, posterior auricular, superficial temporal, maxillary.","topic":"Branch by branch","sec":5,"importance":"core","highYield":"untested"},{"id":"anat3-blood-supply:e5","text":"Superior thyroid: infrahyoid, superior laryngeal, cricothyroid, glandular.","topic":"Branch by branch","sec":5,"importance":"core","highYield":"untested"},{"id":"anat3-blood-supply:e6","text":"Lingual artery is divided into three parts by the hyoglossus; four branches: suprahyoid, dorsal lingual, sublingual, deep lingual.","topic":"Branch by branch","sec":5,"importance":"core","highYield":"untested"},{"id":"anat3-blood-supply:e7","text":"Facial artery crosses the mandible at the anterior border of the masseter and ends as the angular artery.","topic":"Branch by branch","sec":5,"importance":"core","highYield":"untested"},{"id":"anat3-blood-supply:e8","text":"Ascending pharyngeal is the smallest branch of the external carotid.","topic":"Branch by branch","sec":5,"importance":"core","highYield":"untested"},{"id":"anat3-blood-supply:e9","text":"Stylomastoid branch of the posterior auricular artery enters the stylomastoid foramen.","topic":"Branch by branch","sec":5,"importance":"core","highYield":"untested"},{"id":"anat3-blood-supply:e11","text":"Angular vein = supratrochlear + supraorbital. It becomes the facial vein.","topic":"Venous drainage","sec":6,"importance":"core","highYield":"untested"},{"id":"anat3-blood-supply:e12","text":"Retromandibular vein = superficial temporal + maxillary. Anterior division to the facial vein, posterior division to the external jugular.","topic":"Venous drainage","sec":6,"importance":"core","highYield":"untested"},{"id":"anat3-blood-supply:e13","text":"External jugular drains into the subclavian vein; internal jugular continues from the sigmoid sinus and joins the subclavian to form the brachiocephalic.","topic":"Venous drainage","sec":6,"importance":"core","highYield":"untested"},{"id":"anat3-blood-supply:e14","text":"Facial vein connects to the cavernous sinus through the ophthalmic veins and the pterygoid plexus: a route for infection to reach the brain.","topic":"Venous drainage","sec":6,"importance":"core","highYield":"untested"},{"id":"anat3-blood-supply:e15","text":"Lymph: upper face to preauricular, mid face to submandibular, lower lip and chin to submental; then cervical nodes and the jugular trunks.","topic":"Lymphatic drainage","sec":7,"importance":"core","highYield":"untested"}],"vmap":{},"mlevel":{"1gswdzb":"a","v0khkj":"a","16vexr2":"a","1kdmbvh":"a","1svbez2":"a","83gtax":"a","hzvjm5":"a","1wilody":"a","1nidv2j":"a","n7ntar":"a","15uxdcp":"a","3x4wx3":"a","svcno8":"a","r34xf7":"a","nmc0dj":"a","16yd95g":"a","gb8l5w":"a","1180aj3":"a","168mr7m":"a","1wki8bj":"a","p1nh8x":"a","1h89qqu":"a","3daqcl":"a","3224l":"a"},"mapCounts":{"verified":0,"auto":24,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"anat3-blood-supply:s0":{"s":0,"u":["Almost everything in this region is supplied by one artery: the external carotid .","Learn where it starts, where it ends and its eight branches, and the arterial half of the lecture is done."],"dp":[]},"anat3-blood-supply:s1":{"s":1,"u":["The external carotid artery's course and relationships.","Its branches and their important anatomic landmarks."],"dp":[]},"anat3-blood-supply:e0":{"s":2,"u":["Right common carotid from the brachiocephalic trunk; left directly from the aortic arch.","Left common carotid: arises directly from the arch of the aorta, behind the manubrium sterni.","Right common carotid: arises from the brachiocephalic trunk behind the sternoclavicular joint."],"dp":[]},"anat3-blood-supply:e1":{"s":2,"u":["Carotid bifurcation: carotid triangle, upper border of the thyroid cartilage, C3 to C4 disc.","In the neck each common carotid ascends in the carotid sheath and divides in the carotid triangle , at the upper border of the lamina of the thyroid cartilage, opposite the disc between C3 and C4 , into the external and internal carotid arteries."],"dp":[{"h":"Note","t":"Carotid bifurcation : upper border of the thyroid cartilage, C3-C4 , in the carotid triangle. The ECA starts anteromedial to the ICA and ends lateral to it. The ICA has no branches in the neck ; the ECA has eight."}]},"anat3-blood-supply:e2":{"s":3,"u":["External carotid begins anteromedial to the internal carotid and ends lateral to it.","At its origin the artery lies in the carotid triangle, anteromedial to the internal carotid.","With the internal carotid: At first medial to it; as it ascends it passes backward and lateral."],"dp":[{"h":"Why the internal carotid has no branches in the neck","t":"A quick way to tell the two carotids apart in a dissection or an image: the external carotid gives off branches almost immediately, while the internal carotid gives none in the neck at all and heads straight for the carotid canal to supply the brain. If a vessel in the neck is branching, it is the external carotid. Source: AnatomyZone, External carotid artery."}]},"anat3-blood-supply:e3":{"s":3,"u":["It terminates in the parotid gland behind the neck of the mandible as the superficial temporal and maxillary arteries.","In the substance of the parotid gland, behind the neck of the mandible, dividing into the superficial temporal and maxillary arteries.","Within the parotid gland it is crossed by the facial nerve."],"dp":[{"h":"Note","t":"The ECA ends in the parotid gland , behind the neck of the mandible, as the superficial temporal and maxillary arteries. Smallest branch = ascending pharyngeal ."},{"h":"Clinical","t":"Superficial temporal artery in front of the tragus is a pulse point and the biopsy site for giant cell (temporal) arteritis ."}]},"anat3-blood-supply:s4":{"s":4,"u":["In the order the lecture lists them.","A common mnemonic is Some Anatomists Like Freaking Out Poor Medical Students ."],"dp":[]},"anat3-blood-supply:e10":{"s":5,"u":["Maxillary artery: three parts (mandibular, pterygoid, pterygopalatine), five branches each; the middle meningeal enters the foramen spinosum.","Conventionally divided into three parts by the lateral pterygoid: mandibular , pterygoid and pterygopalatine , with five branches from each part.","It supplies the upper and lower jaws, the muscles of mastication, the nose, the palate and the meninges inside the skull (through the middle meningeal artery , which enters the foramen spinosum)."],"dp":[{"h":"Note","t":"Maxillary artery : 3 parts by the lateral pterygoid ; key branch = middle meningeal through the foramen spinosum ."}]},"anat3-blood-supply:e4":{"s":5,"u":["Eight branches: superior thyroid, ascending pharyngeal, lingual, facial, occipital, posterior auricular, superficial temporal, maxillary.","Branches: auricular (back of the pinna and extrinsic auricular muscles), stylomastoid (enters the stylomastoid foramen to supply the middle and inner ear and the facial nerve as it exits), occipital (sternocleidomastoid, digastric, stylohyoid) and posterior tympanic .","Other notable branches: transverse facial, zygomatico-orbital, anterior auricular and middle temporal."],"dp":[{"h":"Memory aid","t":"ECA branches: 'Some Anatomists Like Freaking Out Poor Medical Students' : Superior thyroid, Ascending pharyngeal, Lingual, Facial, Occipital, Posterior auricular, Maxillary, Superficial temporal."}]},"anat3-blood-supply:e5":{"s":5,"u":["Superior thyroid: infrahyoid, superior laryngeal, cricothyroid, glandular.","At the thyroid gland it divides into four terminal branches: infrahyoid (infrahyoid muscles), superior laryngeal (structures within the upper larynx), cricothyroid (cricothyroid muscle) and glandular (superior aspect of the thyroid gland).","Superior thyroid artery Arises from the front of the external carotid, below the tip of the greater cornu of the hyoid bone."],"dp":[]},"anat3-blood-supply:e6":{"s":5,"u":["Lingual artery is divided into three parts by the hyoglossus; four branches: suprahyoid, dorsal lingual, sublingual, deep lingual.","Four main branches: suprahyoid (suprahyoid muscles), dorsal lingual (back of the tongue and throat), sublingual (sublingual gland) and deep lingual (body and tip of the tongue).","Lingual artery The principal artery of the tongue."],"dp":[]},"anat3-blood-supply:e7":{"s":5,"u":["Facial artery crosses the mandible at the anterior border of the masseter and ends as the angular artery.","It then curves upward over the body of the mandible along the anterior border of the masseter, deep to the platysma, and takes a tortuous course toward the angle of the mouth.","Lingual artery The principal artery of the tongue."],"dp":[{"h":"Why the facial artery is so tortuous","t":"The facial artery takes a winding path across the face rather than a straight one. The slack lets the vessel stretch as the mandible moves and the face changes expression, without the artery being put under tension. Its pulse can be felt where it crosses the lower border of the mandible at the anterior border of the masseter, a standard clinical pulse point. Sources: Kenhub, The external carotid artery and its branches; lecture slides."},{"h":"Note","t":"Facial artery crosses the mandible at the anterior border of the masseter (pulse point), runs tortuously to the angle of the mouth and ends as the angular artery ."}]},"anat3-blood-supply:e8":{"s":5,"u":["Ascending pharyngeal is the smallest branch of the external carotid.","Ascending pharyngeal artery The smallest branch, arising posteriorly near the origin of the external carotid.","Occipital artery Arises in the carotid triangle from the posterior aspect of the external carotid about 2 cm from its origin."],"dp":[]},"anat3-blood-supply:e9":{"s":5,"u":["Stylomastoid branch of the posterior auricular artery enters the stylomastoid foramen.","Branches: auricular (back of the pinna and extrinsic auricular muscles), stylomastoid (enters the stylomastoid foramen to supply the middle and inner ear and the facial nerve as it exits), occipital (sternocleidomastoid, digastric, stylohyoid) and posterior tympanic .","Superficial temporal artery A terminal branch."],"dp":[]},"anat3-blood-supply:e11":{"s":6,"u":["Angular vein = supratrochlear + supraorbital. It becomes the facial vein.","Angular: Formed by = Supratrochlear + supraorbital; Drains into = Continues as the facial vein.","Superficial drainage The supratrochlear and supraorbital veins merge at the medial angle of the eye to form the angular vein ."],"dp":[]},"anat3-blood-supply:e12":{"s":6,"u":["Retromandibular vein = superficial temporal + maxillary. Anterior division to the facial vein, posterior division to the external jugular.","Retromandibular: Formed by = Superficial temporal + maxillary; Drains into = Anterior division to the facial vein; posterior division to the posterior auricular vein.","Facial: Formed by = Continuation of the angular vein; Drains into = Joins the anterior division of the retromandibular vein as the common facial vein, then the internal jugular."],"dp":[{"h":"Note","t":"Retromandibular vein = superficial temporal + maxillary veins; anterior division → facial vein (→ common facial → IJV); posterior division + posterior auricular → external jugular . In the parotid, from superficial to deep: facial nerve → retromandibular vein → ECA ."}]},"anat3-blood-supply:e13":{"s":6,"u":["External jugular drains into the subclavian vein; internal jugular continues from the sigmoid sinus and joins the subclavian to form the brachiocephalic.","Internal jugular: Formed by = Continuation of the sigmoid sinus, leaving by the jugular foramen; Drains into = Joins the subclavian vein to form the brachiocephalic vein.","External jugular: Formed by = Posterior auricular + posterior division of the retromandibular; Drains into = Subclavian vein, behind the middle of the clavicle."],"dp":[]},"anat3-blood-supply:e14":{"s":6,"u":["Facial vein connects to the cavernous sinus through the ophthalmic veins and the pterygoid plexus: a route for infection to reach the brain.","The facial vein is also connected to the cavernous sinus through the ophthalmic veins.","The pterygoid plexus has a crucial connection to the cavernous sinus , a potential pathway for infection to spread from the face to the brain."],"dp":[{"h":"The danger area of the face","t":"The lecture's warning about infection spreading to the cavernous sinus has a name: the danger triangle, running from the corners of the mouth to the bridge of the nose. Infection of the upper lip, the vestibule of the nose or the eyelids can travel along the angular, supraorbital and supratrochlear veins to the ophthalmic veins, which drain straight into the cavernous sinus. The second route is the deep facial vein into the pterygoid plexus, which receives an emissary vein from the cavernous sinus through the foramen ovale. That is why squeezing a spot in this area is not as harmless as it looks. Sources: Radiopaedia, Facial-cavernous anastomoses; Radiopaedia, Pterygoid venous plexus."},{"h":"The pterygoid plexus as a pump","t":"The veins of the pterygoid plexus have valves, and the plexus works as a small pump: contractions of the lateral pterygoid squeeze it and help push venous blood back toward the heart. It also explains why a badly placed dental injection into the plexus can leak blood into the orbit and give the patient a black eye. Sources: Radiopaedia, Pterygoid venous plexus; Brainscape, Veins of head and neck."},{"h":"Clinical","t":"Danger triangle of the face : the facial vein connects to the cavernous sinus via the ophthalmic veins and the pterygoid plexus (deep facial vein) → squeezing a spot near the nose can seed cavernous sinus thrombosis."}]},"anat3-blood-supply:e15":{"s":7,"u":["Lymph: upper face to preauricular, mid face to submandibular, lower lip and chin to submental; then cervical nodes and the jugular trunks.","Lower face: lower lip, chin, apex of the tongue: Submental nodes, under the chin.","Central and lateral face: cheeks, upper lip, lateral aspects of the nose: Submandibular nodes, under the jaw."],"dp":[{"h":"Note","t":"Lymph : upper face and lateral lids → preauricular/parotid ; cheeks, upper lip, lateral nose → submandibular ; lower lip centre, chin, tongue tip → submental ; all then to the deep cervical chain."}]}},"meta":{"1gswdzb":{"a":"recall","vg":"anat3-blood-supply:e1/recall/1"},"v0khkj":{"a":"recall","vg":"anat3-blood-supply:e0/recall/1"},"16vexr2":{"a":"relationship","vg":"anat3-blood-supply:e2/relationship/1"},"1kdmbvh":{"a":"recall","vg":"anat3-blood-supply:e3/recall/1"},"1svbez2":{"a":"recall","vg":"anat3-blood-supply:e5/recall/1"},"83gtax":{"a":"recall","vg":"anat3-blood-supply:e5/recall/2"},"hzvjm5":{"a":"recall","vg":"anat3-blood-supply:e6/recall/1"},"1wilody":{"a":"recall","vg":"anat3-blood-supply:e6/recall/2"},"1nidv2j":{"a":"recall","vg":"anat3-blood-supply:e7/recall/1"},"n7ntar":{"a":"recall","vg":"anat3-blood-supply:e9/recall/1"},"15uxdcp":{"a":"recall","vg":"anat3-blood-supply:e8/recall/1"},"3x4wx3":{"a":"recall","vg":"anat3-blood-supply:e9/recall/2"},"svcno8":{"a":"recall","vg":"anat3-blood-supply:e10/recall/1"},"r34xf7":{"a":"recall","vg":"anat3-blood-supply:e10/recall/2"},"nmc0dj":{"a":"recall","vg":"anat3-blood-supply:e11/recall/1"},"16yd95g":{"a":"recall","vg":"anat3-blood-supply:e12/recall/1"},"gb8l5w":{"a":"recall","vg":"anat3-blood-supply:e13/recall/1"},"1180aj3":{"a":"recall","vg":"anat3-blood-supply:e13/recall/2"},"168mr7m":{"a":"recall","vg":"anat3-blood-supply:e15/recall/1"},"1wki8bj":{"a":"recall","vg":"anat3-blood-supply:e3/recall/2"},"p1nh8x":{"a":"recall","vg":"anat3-blood-supply:e3/recall/1"},"1h89qqu":{"a":"recall","vg":"anat3-blood-supply:e4/recall/1"},"3daqcl":{"a":"recall","vg":"anat3-blood-supply:e11/recall/1"},"3224l":{"a":"recall","vg":"anat3-blood-supply:e4/recall/2"}},"explRev":"c3d132bfe65f"};
